/**
 * Shared in-memory cache state for HTTP module caching.
 *
 * Manages the LRU caches, processing stacks, and distributed cache refresh
 * tracking. Provides dependency injection for testing.
 *
 * @module transforms/esm/http-cache-state
 */
import { LRUCache } from "../../utils/lru-wrapper.js";
import { HTTP_MODULE_CACHE_MAX_ENTRIES } from "../../utils/constants/cache.js";
import { registerCache } from "../../utils/memory/index.js";
import { __clearInFlightHttpFetches, inFlightHttpFetches, processingStackStorage, } from "./in-flight-manager.js";
const defaultCachedPaths = new LRUCache({
    maxEntries: HTTP_MODULE_CACHE_MAX_ENTRIES,
});
const defaultProcessingStack = new Set();
/** Tracks last TTL refresh per hash. Refresh every 4h to keep 20h+ remaining (24h total). */
const defaultLastDistributedRefresh = new LRUCache({
    maxEntries: HTTP_MODULE_CACHE_MAX_ENTRIES,
});
/** Injected caches for testing */
let injectedCachedPaths = null;
let injectedProcessingStack = null;
let injectedLastDistributedRefresh = null;
function getCacheEntryCount(cache) {
    const size = cache.size;
    return typeof size === "number" ? size : -1;
}
function estimateStringCacheBytes(cache) {
    const entries = cache.entries;
    if (typeof entries !== "function")
        return undefined;
    let total = 0;
    try {
        for (const [key, value] of entries.call(cache)) {
            total += String(key).length + String(value).length;
        }
    }
    catch (_) {
        return undefined;
    }
    return total;
}
registerCache("http-bundle-paths", () => ({
    name: "http-bundle-paths",
    entries: getCacheEntryCount(getCachedPaths()),
    maxEntries: HTTP_MODULE_CACHE_MAX_ENTRIES,
    estimatedSizeBytes: estimateStringCacheBytes(getCachedPaths()),
}));
registerCache("http-bundle-ttl-refreshes", () => ({
    name: "http-bundle-ttl-refreshes",
    entries: getCacheEntryCount(getLastDistributedRefresh()),
    maxEntries: HTTP_MODULE_CACHE_MAX_ENTRIES,
}));
registerCache("http-bundle-in-flight", () => ({
    name: "http-bundle-in-flight",
    entries: inFlightHttpFetches.size,
}));
export function getCachedPaths() {
    return injectedCachedPaths ?? defaultCachedPaths;
}
export function getProcessingStack() {
    if (injectedProcessingStack)
        return injectedProcessingStack;
    return processingStackStorage.getStore() ?? defaultProcessingStack;
}
export function getLastDistributedRefresh() {
    return injectedLastDistributedRefresh ?? defaultLastDistributedRefresh;
}
/** Check if a test-injected processing stack is active (used to skip AsyncLocalStorage.run). */
export function hasInjectedProcessingStack() {
    return injectedProcessingStack !== null;
}
/**
 * Inject custom caches for testing.
 * Call with null to restore default behavior.
 */
export function __injectCachesForTests(caches) {
    if (caches === null) {
        injectedCachedPaths = null;
        injectedProcessingStack = null;
        injectedLastDistributedRefresh = null;
        __clearInFlightHttpFetches();
        return;
    }
    if (caches.cachedPaths !== undefined)
        injectedCachedPaths = caches.cachedPaths;
    if (caches.processingStack !== undefined)
        injectedProcessingStack = caches.processingStack;
    if (caches.lastDistributedRefresh !== undefined) {
        injectedLastDistributedRefresh = caches.lastDistributedRefresh;
    }
}
